-- Table: hrm_salary_payment_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_salary_payment_detail (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    salary_payment_id   BIGINT NOT NULL REFERENCES hrm_salary_payment(id) ON DELETE CASCADE,
    line_number         INTEGER NOT NULL CHECK (line_number > 0),
    employee_id         BIGINT NOT NULL REFERENCES masterdata_employee(id),
    amount              NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (amount >= 0),
    bank_account_number VARCHAR(100),
    bank_name           VARCHAR(100),
    payment_reference   VARCHAR(100),
    UNIQUE (salary_payment_id, line_number)
);
